{#- =====================================================================
    Payment Entry -> Nepal bank cheque overlay  (A4 CARRIER method)

    Prints a full A4 page. The cheque lies FLAT (landscape) near the top-
    left of that A4 -- NO rotation. Feed plain A4 portrait through the
    printer as normal.

    WORKFLOW (two passes on the SAME A4 sheet):
      1. Print WITH the guide  ->  add  &cheque_guide=1  to the print URL.
         A dashed box + ruler shows where the cheque goes. Print on blank A4.
      2. Lay the cheque inside the dashed box: BANK LOGO at the TOP-LEFT
         corner, DATE boxes at the TOP-RIGHT. Tape the top edge down.
      3. Print again WITHOUT the guide (normal). The text lands on the cheque.

    Always print at 100% / Actual Size, margins NONE, to the LBP2900.

    Field positions below are millimetres from the CHEQUE's own top-left
    corner (so they match how you measure on the cheque). MX/MY place the
    cheque on the A4. Nudge and reprint.
    ===================================================================== -#}

{%- set A4_W = 210.0 -%}{%- set A4_H = 297.0 -%}
{%- set CHEQUE_W = 190.5 -%}{%- set CHEQUE_H = 88.9 -%}
{%- set MX = 10.0 -%}{%- set MY = 15.0 -%}   {#- cheque top-left position on the A4, mm -#}
{%- set FONT = 11 -%}
{%- set ROTATE = 90 -%}                       {#- VERTICAL feed: 90 or 270 -- flip if text prints upside down -#}
{%- set USE_BS = 0 -%}                        {#- 1 = Nepali BS date, 0 = posting_date as-is -#}

{#- ---- field positions: mm from the CHEQUE top-left ---- -#}
{%- set DATE_X = 140.0 -%}{%- set DATE_Y = 10.0 -%}{%- set DATE_GAP = 3.8 -%}
{%- set PAYEE_X = 44.0 -%}{%- set PAYEE_Y = 22.0 -%}
{%- set WORDS_X = 29.0 -%}{%- set WORDS_Y = 28.5 -%}{%- set WORDS_W = 100.0 -%}{%- set WORDS_LH = 7.0 -%}
{%- set FIG_X = 142.6 -%}{%- set FIG_Y = 31.0 -%}{%- set FIG_W = 50.0 -%}

{#- ---- date digits DDMMYYYY ---- -#}
{%- if USE_BS -%}
  {%- set _ds = bs_date_str(doc.posting_date, "") -%}
  {%- set date_digits = _ds[6:8] ~ _ds[4:6] ~ _ds[0:4] -%}
{%- else -%}
  {%- set _g = frappe.utils.getdate(doc.posting_date) -%}
  {%- set date_digits = "%02d"|format(_g.day) ~ "%02d"|format(_g.month) ~ "%04d"|format(_g.year) -%}
{%- endif -%}

{%- set _words = frappe.utils.money_in_words(doc.paid_amount, doc.paid_from_account_currency or "NPR") -%}

{#- ---- payee name = the party's name (blank when there is no party, e.g. internal transfer) ---- -#}
{%- set _payee = doc.party_name or doc.party or "" -%}

{%- set GUIDE = frappe.form_dict.get("cheque_guide") -%}

{#- rotated footprint on the A4, and cheque top-left placement so the rotated box lands at MX,MY -#}
{%- set FP_W = CHEQUE_H -%}{%- set FP_H = CHEQUE_W -%}
{%- if ROTATE == 270 -%}
  {%- set CHEQUE_LEFT = MX -%}{%- set CHEQUE_TOP = MY + CHEQUE_W -%}
{%- else -%}
  {%- set CHEQUE_LEFT = MX + CHEQUE_H -%}{%- set CHEQUE_TOP = MY -%}
{%- endif -%}

<style>
  @page { size: A4 portrait; margin: 0; }
  html, body { margin: 0; padding: 0; }
  #cheque-page {
    position: relative; width: {{ A4_W }}mm; height: {{ A4_H }}mm; overflow: hidden;
    font-family: "DejaVu Sans", Arial, sans-serif;
  }
  #cheque {
    position: absolute;
    width: {{ CHEQUE_W }}mm; height: {{ CHEQUE_H }}mm;
    font-size: {{ FONT }}pt; color: #000; line-height: 1.1;
    transform: rotate({{ ROTATE }}deg); transform-origin: top left;
  }
  #cheque .f { position: absolute; white-space: nowrap; }
  #cheque .date {
    font-family: "DejaVu Sans Mono", "Courier New", monospace;
    letter-spacing: {{ DATE_GAP }}mm; font-weight: 600;
  }
  #cheque .words { white-space: normal; width: {{ WORDS_W }}mm; line-height: {{ WORDS_LH }}mm; }
  #cheque .fig { width: {{ FIG_W }}mm; text-align: left; font-weight: 600; }
  {%- if GUIDE %}
  #cheque { outline: 0.35mm dashed #0060cc; }
  .cmark { position: absolute; width: 7mm; height: 7mm; }
  #note {
    position: absolute; left: {{ MX }}mm; top: {{ MY + FP_H + 8 }}mm;
    width: 185mm; font-size: 10pt; color: #c00; line-height: 1.4;
  }
  {%- endif %}
</style>

<div id="cheque-page">
  {%- if GUIDE %}
    {#- L-shaped corner marks just OUTSIDE the cheque box, so they stay visible next to the cheque -#}
    <div class="cmark" style="left:{{ MX-1 }}mm; top:{{ MY-1 }}mm; border-left:0.4mm solid #c00; border-top:0.4mm solid #c00;"></div>
    <div class="cmark" style="left:{{ MX+FP_W-6 }}mm; top:{{ MY-1 }}mm; border-right:0.4mm solid #c00; border-top:0.4mm solid #c00;"></div>
    <div class="cmark" style="left:{{ MX-1 }}mm; top:{{ MY+FP_H-6 }}mm; border-left:0.4mm solid #c00; border-bottom:0.4mm solid #c00;"></div>
    <div class="cmark" style="left:{{ MX+FP_W-6 }}mm; top:{{ MY+FP_H-6 }}mm; border-right:0.4mm solid #c00; border-bottom:0.4mm solid #c00;"></div>
    <div id="note">
      &#9654; Place the cheque inside the dashed box &mdash; <b>bank logo at TOP-LEFT, date boxes at TOP-RIGHT</b>.
      Tape the top edge, then print this document again <b>without</b> &amp;cheque_guide=1.<br>
      Print at 100% / Actual Size, margins none, on the LBP2900.
    </div>
  {%- endif %}

  <div id="cheque" style="left:{{ CHEQUE_LEFT }}mm; top:{{ CHEQUE_TOP }}mm;">
    {%- if GUIDE %}<div class="ruler"></div>{%- endif %}
    <div class="f date" style="left:{{ DATE_X }}mm; top:{{ DATE_Y }}mm;">{{ date_digits }}</div>
    <div class="f" style="left:{{ PAYEE_X }}mm; top:{{ PAYEE_Y }}mm;">{{ _payee }}</div>
    <div class="f words" style="left:{{ WORDS_X }}mm; top:{{ WORDS_Y }}mm;">{{ _words }}</div>
    <div class="f fig" style="left:{{ FIG_X }}mm; top:{{ FIG_Y }}mm;">{{ "{:,.2f}".format(doc.paid_amount) }}</div>
  </div>
</div>
